'use client';

import React from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Camera, FileQuestion, HelpCircle } from 'lucide-react';

export interface IdentificationRefusalCardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  refusalReason?: string;
  onRetake: () => void;
  onSaveUnidentified: () => void;
}

export function IdentificationRefusalCard({
  open,
  onOpenChange,
  refusalReason,
  onRetake,
  onSaveUnidentified,
}: IdentificationRefusalCardProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md rounded-2xl p-6 bg-card border border-border shadow-2xl">
        <DialogHeader className="space-y-3 text-left">
          <div className="w-12 h-12 rounded-full bg-amber-500/10 border border-amber-500/20 flex items-center justify-center text-amber-600 dark:text-amber-400">
            <HelpCircle className="w-6 h-6" />
          </div>
          <DialogTitle className="text-xl font-bold tracking-tight text-foreground">
            Organism not recognized
          </DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground leading-relaxed">
            {refusalReason ||
              'We noticed an inanimate object or human. Treads is designed to track living organisms in nature. Try a closer shot of leaves, bark, or wildlife.'}
          </DialogDescription>
        </DialogHeader>

        <div className="p-3 my-2 rounded-xl bg-muted/50 border border-border/60 text-xs text-muted-foreground leading-snug">
          Tip: Fill the viewfinder with the organism&apos;s distinguishing features: leaf veins, petals, bark texture, or plumage.
        </div>

        <DialogFooter className="flex flex-col-reverse sm:flex-row gap-2 pt-2">
          <Button
            type="button"
            variant="outline"
            onClick={onSaveUnidentified}
            className="w-full sm:w-auto flex-1 min-h-[44px] text-foreground font-medium rounded-xl cursor-pointer"
          >
            <FileQuestion className="w-4 h-4 mr-2 text-muted-foreground" />
            Keep as Unidentified Note
          </Button>

          <Button
            type="button"
            onClick={onRetake}
            className="w-full sm:w-auto flex-1 min-h-[44px] bg-[#F35C2B] hover:bg-[#F35C2B]/90 text-white font-semibold rounded-xl shadow-md transition-transform active:scale-95 cursor-pointer"
          >
            <Camera className="w-4 h-4 mr-2" />
            Retake Photo
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import React from 'react';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Check, CheckCircle2, FileQuestion, RotateCcw, Sparkles } from 'lucide-react';
import type { Candidate } from '@/lib/db';

export interface CandidatePickerSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  candidates: Candidate[];
  onConfirmCandidate: (candidate: Candidate) => void;
  onSaveUnidentified: () => void;
  onRetake: () => void;
}

export function CandidatePickerSheet({
  open,
  onOpenChange,
  candidates,
  onConfirmCandidate,
  onSaveUnidentified,
  onRetake,
}: CandidatePickerSheetProps) {
  // Check if all candidates have low confidence ('Unsure')
  const allUnsure = candidates.length > 0 && candidates.every((c) => c.confidence === 'Unsure');

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="max-h-[85vh] flex flex-col gap-4 rounded-t-2xl border-t border-border bg-card p-6 shadow-2xl overflow-y-auto"
      >
        <SheetHeader className="text-left space-y-1">
          <div className="flex items-center gap-2">
            <div className="p-1.5 rounded-lg bg-[#F35C2B]/10 text-[#F35C2B]">
              <Sparkles className="w-4 h-4" />
            </div>
            <SheetTitle className="text-lg font-semibold tracking-tight text-foreground">
              Candidate Species
            </SheetTitle>
          </div>
          <SheetDescription className="text-xs text-muted-foreground">
            Tap the species that best matches your observation to confirm and generate Wikipedia facts.
          </SheetDescription>
        </SheetHeader>

        {/* Low Confidence Warning Notice if applicable */}
        {allUnsure && (
          <div className="p-3 rounded-xl bg-amber-500/10 border border-amber-500/25 text-xs text-amber-800 dark:text-amber-300 leading-snug">
            Lighting or angle makes this tricky. If none of these match, you can save as an unidentified specimen or retake the photo.
          </div>
        )}

        {/* Candidates List */}
        <div className="flex flex-col gap-3 py-1">
          {candidates.map((candidate, idx) => (
            <Card
              key={`${candidate.scientificName}-${idx}`}
              onClick={() => onConfirmCandidate(candidate)}
              className="cursor-pointer border-border/80 hover:border-[#F35C2B]/60 hover:shadow-md transition-all active:scale-[0.99] group bg-card/60 backdrop-blur-xs"
            >
              <CardHeader className="p-4 pb-2">
                <div className="flex items-start justify-between gap-2">
                  <div className="space-y-0.5">
                    <CardTitle className="text-base font-bold tracking-tight text-foreground group-hover:text-[#F35C2B] transition-colors">
                      {candidate.commonName}
                    </CardTitle>
                    <CardDescription className="text-xs font-serif italic text-muted-foreground">
                      {candidate.scientificName}
                    </CardDescription>
                  </div>

                  {/* Confidence Badge */}
                  <Badge
                    variant={
                      candidate.confidence === 'Likely'
                        ? 'secondary'
                        : candidate.confidence === 'Possible'
                        ? 'outline'
                        : 'outline'
                    }
                    className={`text-xs px-2 py-0.5 capitalize ${
                      candidate.confidence === 'Likely'
                        ? 'bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 border-emerald-500/30'
                        : candidate.confidence === 'Possible'
                        ? 'bg-amber-500/15 text-amber-700 dark:text-amber-400 border-amber-500/30'
                        : 'bg-muted text-muted-foreground border-border'
                    }`}
                  >
                    {candidate.confidence}
                  </Badge>
                </div>
              </CardHeader>

              <CardContent className="p-4 pt-1 flex items-center justify-between text-xs text-muted-foreground">
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="text-[11px] capitalize border-border/60">
                    {candidate.kind}
                  </Badge>
                  {candidate.verified && (
                    <Badge
                      variant="secondary"
                      className="text-[11px] flex items-center gap-1 bg-[#F35C2B]/10 text-[#F35C2B] border border-[#F35C2B]/20"
                    >
                      <CheckCircle2 className="w-3 h-3" />
                      Verified Taxon
                    </Badge>
                  )}
                </div>

                <span className="flex items-center gap-1 text-[11px] text-[#F35C2B] opacity-0 group-hover:opacity-100 transition-opacity font-medium">
                  Confirm <Check className="w-3 h-3" />
                </span>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Fallback Action Buttons */}
        <div className="flex items-center gap-3 pt-2 border-t border-border/60">
          <Button
            type="button"
            variant="outline"
            onClick={onRetake}
