args.CodeContent:
/**
 * Safety and verification pipeline for Wikipedia-derived biological facts.
 * Enforces strict client-side & server-side regex scrubber dropping all
 * edibility, toxicity, culinary, foraging, or medicinal claims.
 * Per FACT-03, FACT-04, and Decisions D-10, D-11.
 */

export const EDIBILITY_SAFETY_REGEX =
  /\b(edible|inedible|eat\w*|taste|tasty|culinary|recipe|salad|soup|boil\w*|cook\w*|forag\w*|medicinal|remedy|cure|toxic|poison\w*|consumption)\b/i;

export interface FactItem {
  sentenceNumber: number;
  text: string;
}

/**
 * Checks whether a candidate sentence or text contains forbidden safety keywords
 * relating to edibility, toxicity, foraging, or medicinal ingestion.
 */
export function containsSafetyViolations(text: string): boolean {
  if (!text || typeof text !== 'string') return true;
  return EDIBILITY_SAFETY_REGEX.test(text);
}

/**
 * Strips any embedded citation brackets (e.g. "[1]", "(2)") from generated text
 * to ensure pure prose is stored and displayed cleanly.
 */
export function sanitizeFactText(text: string): string {
  return text
    .replace(/\[\d+\]/g, '')
    .replace(/\(\d+\)/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Filters a list of synthesized facts against safety rules and sentence index bounds.
 * Discards any fact that:
 * 1. References an out-of-bounds sentence number (< 1 or > maxSentenceIndex).
 * 2. Matches the edibility / toxic advice regex blacklist.
 * 3. Has an empty or overly short text body (< 5 characters).
 */
export function validateCitations(
  facts: FactItem[],
  maxSentenceIndex: number
): FactItem[] {
  if (!Array.isArray(facts) || maxSentenceIndex < 1) return [];

  return facts
    .map((fact) => ({
      sentenceNumber: Number(fact.sentenceNumber),
      text: sanitizeFactText(fact.text),
    }))
    .filter((fact) => {
      // 1. Bounds check
      if (
        !Number.isInteger(fact.sentenceNumber) ||
        fact.sentenceNumber < 1 ||
        fact.sentenceNumber > maxSentenceIndex
      ) {
        return false;
      }

      // 2. Length check
      if (fact.text.length < 5) {
        return false;
      }

      // 3. Edibility / toxicity violation check
      if (containsSafetyViolations(fact.text)) {
        return false;
      }

      return true;
    });
}

/**
 * Deterministic fallback provider (FACT-04):
 * When LLM synthesis fails or all facts are dropped by the safety scrubber,
 * returns sentence #1 of the verified Wikipedia lead section.
 */
export function getFallbackFact(
  leadSentences: Array<{ index: number; text: string }>
): FactItem[] {
  if (!leadSentences || leadSentences.length === 0) {
    return [
      {
        sentenceNumber: 1,
        text: 'A documented wild organism recorded during your exploration.',
      },
    ];
  }

  const first = leadSentences[0];
  const sanitized = sanitizeFactText(first.text);

  // Even for sentence #1, verify safety; if violated, provide neutral fallback
  if (containsSafetyViolations(sanitized)) {
    return [
      {
        sentenceNumber: first.index,
        text: 'A native biological organism documented in field observations.',
      },
    ];
  }

  return [
    {
      sentenceNumber: first.index,
      text: sanitized,
    },
  ];
}

import {
  containsSafetyViolations,
  validateCitations,
  getFallbackFact,
  sanitizeFactText,
} from '../lib/facts-safety';

async function runTests() {
  console.log('Testing Edibility & Toxicity Safety Scrubber...');

  // Test 1: Positive detection of safety violations
  console.log('\n--- 1. Testing Forbidden Edibility & Toxicity Claims ---');
  const violations = [
    'The berries are edible when cooked into a jam.',
    'Leaves can be eaten raw in salads.',
    'Traditionally used as a medicinal remedy for fevers.',
    'Roots contain a toxic alkaloid that causes nausea.',
    'A tasty mushroom popular among foragers.',
    'Never boil or cook the seeds as they are poisonous.',
    'Foraging guide recommends picking young shoots.',
    'Safe for human consumption.',
  ];

  for (const text of violations) {
    const isViolating = containsSafetyViolations(text);
    console.log(`Checking: "${text}" -> Violated: ${isViolating}`);
    if (!isViolating) {
      throw new Error(`Failed to detect safety violation in: "${text}"`);
    }
  }
  console.log('✓ All 8 dangerous claims caught by regex scrubber.');

  // Test 2: Safe biological facts should NOT trigger violations
  console.log('\n--- 2. Testing Safe Biological Statements ---');
  const safeStatements = [
    'Quercus alba can live for over 450 years in North American temperate forests.',
    'Its bark is light ash-gray and features scaly, irregular plates.',
    'The leaves feature 7 to 9 rounded lobes with deep sinuses.',
    'Acorns mature in a single season and drop in early autumn.',
  ];

  for (const text of safeStatements) {
    const isViolating = containsSafetyViolations(text);
    console.log(`Checking: "${text}" -> Violated: ${isViolating}`);
    if (isViolating) {
      throw new Error(`Safe statement falsely flagged: "${text}"`);
    }
  }
  console.log('✓ All safe biological statements passed cleanly.');

  // Test 3: Citation validator filtering and bounds checking
  console.log('\n--- 3. Testing Citation Validation & Bounds Checking ---');
  const candidateFacts = [
    { sentenceNumber: 1, text: 'Quercus alba is a preeminent North American hardwood.' },
    { sentenceNumber: 2, text: 'The sweet acorns are edible when roasted in an oven.' }, // Edible -> MUST DISCARD
    { sentenceNumber: 4, text: 'It can grow up to 30 meters tall [4].' },
    { sentenceNumber: 99, text: 'Out of bounds citation number.' }, // Index 99 > max 10 -> MUST DISCARD
    { sentenceNumber: -1, text: 'Negative index citation.' }, // Invalid -> MUST DISCARD
    { sentenceNumber: 3, text: 'hi' }, // Too short -> MUST DISCARD
  ];

  const filtered = validateCitations(candidateFacts, 10);
  console.log('Filtered valid facts:', filtered);
  if (filtered.length !== 2) {
    throw new Error(`Expected exactly 2 valid facts, got ${filtered.length}`);
  }
  if (filtered[0].sentenceNumber !== 1 || filtered[1].sentenceNumber !== 4) {
    throw new Error('Unexpected sentence indices in filtered facts!');
  }
  if (filtered[1].text.includes('[4]')) {
    throw new Error('Embedded citation bracket [4] was not stripped from text!');
  }
  console.log('✓ Citation validator filtered invalid/toxic items and stripped brackets.');

  // Test 4: Deterministic Fallback on 0 facts
  console.log('\n--- 4. Testing Sentence #1 Fallback ---');
  const fallback = getFallbackFact([
    { index: 1, text: 'Quercus alba is a widespread oak species found throughout central forests.' },
    { index: 2, text: 'Bark is pale gray.' },
  ]);
  console.log('Fallback fact:', fallback);
  if (fallback.length !== 1 || fallback[0].sentenceNumber !== 1) {
    throw new Error('Fallback failed to return sentence #1!');
  }
  console.log('✓ Fallback to sentence #1 verified.');

  console.log('\n=============================================');
  console.log('✓ All Facts Safety Scrubber tests passed!');
  console.log('=============================================');
}

runTests().catch((err) => {
  console.error('Test failed:', err);
  process.exit(1);
});

import { NextRequest, NextResponse } from 'next/server';
import { checkRateLimit } from '@/lib/rate-limit';
import { getWikipediaLeadSentences } from '@/lib/wikipedia';
import {
  validateCitations,
  containsSafetyViolations,
  getFallbackFact,
  sanitizeFactText,
  FactItem,
} from '@/lib/facts-safety';
import { createGoogleGenerativeAI } from '@ai-sdk/google';
import { generateObject } from 'ai';
import { z } from 'zod';

const FactsSchema = z.object({
  summary: z
    .string()
    .describe('A crisp, educational 2-3 sentence overview of this organism (max 40 words).'),
  facts: z
    .array(
      z.object({
        sentenceNumber: z
          .number()
          .int()
          .describe(
            'The exact 1-indexed sentence number from the provided Wikipedia extract where this fact was derived.'
          ),
        text: z
          .string()
          .describe(
            'An engaging biological or ecological fact (max 20 words). Strictly avoid any claims about edibility, recipes, taste, foraging, medicinal remedies, or toxicity.'
          ),
      })
    )
    .describe('Up to 3 distinct biological facts citing source sentence numbers.'),
});

export interface FactsResponse {
  success: boolean;
  summary: string;
  facts: FactItem[];
  sourceUrl: string;
  sentences: Array<{ index: number; text: string }>;
  cached?: boolean;
  mock?: boolean;
  warning?: string;
}

// In-memory cache by Wikipedia title (per FACT-06)
const factsCache = new Map<string, FactsResponse>();

export async function POST(req: NextRequest) {
  const rateLimit = await checkRateLimit(req, 'facts');
  if (!rateLimit.success) {
    return NextResponse.json(
      { error: 'Rate limit exceeded for facts generation' },
      { status: 429, headers: rateLimit.headers }
    );
  }

  let body: {
    wikipediaTitle?: string;
    scientificName?: string;
    commonName?: string;
  };

  try {
    body = await req.json();
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON request body' },
      { status: 400, headers: rateLimit.headers }
    );
  }

  const title = body.wikipediaTitle || body.scientificName || body.commonName;
  if (!title) {
    return NextResponse.json(
      { error: 'Missing wikipediaTitle or species identifier in request' },
      { status: 400, headers: rateLimit.headers }
    );
  }

  const cacheKey = title.trim().toLowerCase();
  if (factsCache.has(cacheKey)) {
    const cached = factsCache.get(cacheKey)!;
    return NextResponse.json(
      { ...cached, cached: true },
      { status: 200, headers: rateLimit.headers }
    );
  }

  // 1. Fetch Wikipedia lead extract segmented into indexed sentences
  const wikiData = await getWikipediaLeadSentences(title);
  if (!wikiData.sentences || wikiData.sentences.length === 0) {
    return NextResponse.json(
      {
        error: `Could not retrieve Wikipedia lead extract for "${title}"`,
        sourceUrl: wikiData.sourceUrl,
      },
      { status: 404, headers: rateLimit.headers }
    );
  }

  const apiKey = process.env.GOOGLE_GENERATIVE_AI_API_KEY;

  // 2. Mock Fallback when Google AI API key is not configured
  if (!apiKey) {
    const fallbackFacts: FactItem[] = wikiData.sentences.slice(0, 3).map((s) => ({
      sentenceNumber: s.index,
      text: sanitizeFactText(s.text.split('.')[0] + '.'),
    }));

    const mockResponse: FactsResponse = {
      success: true,
      mock: true,
      warning: 'GOOGLE_GENERATIVE_AI_API_KEY not configured. Returning Wikipedia extract fallback.',
      summary: sanitizeFactText(wikiData.sentences[0].text),
      facts: validateCitations(fallbackFacts, wikiData.sentences.length),
      sourceUrl: wikiData.sourceUrl,
      sentences: wikiData.sentences,
    };

    factsCache.set(cacheKey, mockResponse);
    return NextResponse.json(mockResponse, {
      status: 200,
      headers: rateLimit.headers,
    });
  }

  // 3. Grounded Synthesis via Gemma/Gemini
  const modelId = process.env.FACTS_MODEL_ID || 'gemini-2.0-flash';

  try {
    const google = createGoogleGenerativeAI({ apiKey });
    const model = google(modelId);

    const numberedSentencesText = wikiData.sentences
      .map((s) => `[${s.index}] ${s.text}`)
      .join('\n');

    const prompt = `You are a nature educator synthesizing facts about ${title} for field naturalists.

Here is the verified lead section from Wikipedia:
${numberedSentencesText}

INSTRUCTIONS:
1. Write a short summary (max 40 words) describing the organism.
2. Select up to 3 interesting biological facts (max 20 words each).
3. For each fact, cite the exact sentence index where the information was found.
4. STRICT NEGATIVE CONSTRAINT: Do NOT include any claims about edibility, foraging, culinary recipes, taste, medicinal remedies, cures, or human toxicity. If a sentence mentions these, ignore it completely.`;

    const { object } = await generateObject({
      model,
      schema: FactsSchema,
      prompt,
    });

    // 4. Multi-layer safety scrubbing and citation validation
    let validFacts = validateCitations(object.facts, wikiData.sentences.length);

    // If all facts were dropped or none generated, use verified Sentence #1 fallback (FACT-04)
    if (validFacts.length === 0) {
      validFacts = getFallbackFact(wikiData.sentences);
    }

    // Clean and verify summary
    let summary = sanitizeFactText(object.summary);
    if (containsSafetyViolations(summary) || summary.length < 10) {
      summary = sanitizeFactText(wikiData.sentences[0].text);
    }

    const responsePayload: FactsResponse = {
      success: true,
      summary,
      facts: validFacts,
      sourceUrl: wikiData.sourceUrl,
      sentences: wikiData.sentences,
      cached: false,
    };

    factsCache.set(cacheKey, responsePayload);

    return NextResponse.json(responsePayload, {
      status: 200,
      headers: rateLimit.headers,
    });
  } catch (err) {
    console.error('Facts generation failed, applying deterministic fallback:', err);
    // Deterministic fallback ensures no blank screens
    const fallbackResponse: FactsResponse = {
      success: true,
      summary: sanitizeFactText(wikiData.sentences[0].text),
      facts: getFallbackFact(wikiData.sentences),
      sourceUrl: wikiData.sourceUrl,
      sentences: wikiData.sentences,
      warning: 'AI generation error. Reverted to verified Wikipedia extract.',
    };

    return NextResponse.json(fallbackResponse, {
      status: 200,
      headers: rateLimit.headers,
    });
  }
}

